package com.campus.lostfound.config;import com.campus.lostfound.entity.*;import com.campus.lostfound.repository.*;import org.springframework.boot.CommandLineRunner;import org.springframework.context.annotation.*;import org.springframework.security.crypto.password.PasswordEncoder;import java.time.LocalDate;@Configuration public class DataInitializer{@Bean CommandLineRunner seed(UserRepository users,ItemRepository items,PasswordEncoder enc){return args->{if(!users.existsByEmailIgnoreCase("admin@campus.edu"))users.save(new Admin("Campus Admin","admin@campus.edu",enc.encode("Admin@123")));Student s;if(!users.existsByEmailIgnoreCase("student@campus.edu"))s=users.save(new Student("Aarav Sharma","student@campus.edu",enc.encode("Student@123"),"CSE2025001"));else s=(Student)users.findByEmailIgnoreCase("student@campus.edu").orElseThrow();if(items.count()==0){LostItem l=new LostItem("Blue water bottle","Accessories","Library - Ground Floor",LocalDate.now().minusDays(1),"Steel bottle with a small mountain sticker.",s);l.setStatus(ItemStatus.APPROVED);FoundItem f=new FoundItem("Blue steel bottle","Accessories","Central Library",LocalDate.now(),"Found near the reading area.",s);f.setStatus(ItemStatus.APPROVED);items.save(l);items.save(f);}};}}
